package org.eclipse.rdf4j.query.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.lang.reflect.Method;
import java.util.Set;

import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Dataset;
import org.junit.jupiter.api.Test;

class BlankNodeDatasetTest {
	@Test
	void resourceGraphAccessIsAdditiveAndPreservesBlankNodeIdentity() throws Exception {
		Resource graph = SimpleValueFactory.getInstance().createBNode("graph");
		SimpleDataset dataset = new SimpleDataset();
		// Reflection lets the API compatibility regression run against the pre-extension interface.
		Method add = SimpleDataset.class.getMethod("addNamedGraph", Resource.class);
		add.invoke(dataset, graph);
		assertEquals(Set.of(graph), Dataset.class.getMethod("getNamedGraphResources").invoke(dataset));
		assertThrows(IllegalStateException.class, dataset::getNamedGraphs);
		Dataset merged = FallbackDataset.fallback(new SimpleDataset(), dataset);
		assertEquals(Set.of(graph), Dataset.class.getMethod("getNamedGraphResources").invoke(merged));
		assertThrows(IllegalStateException.class, merged::getNamedGraphs);
	}
}
